class Context {
    fun execute(rule: Rule, autocorrect: Boolean) {
        if (autocorrect) {
            executeWithApprove(rule, node)
        } else {
            executeLegacy(rule, node)
        }
    }

    private fun executeLegacy(rule: Rule, node: Node) {
        rule.beforeVisit(node, emit)
        node.children.forEach { child -> executeLegacy(rule, child) }
        rule.afterVisit(node, emit)
    }

    private fun executeWithApprove(rule: Rule, node: Node) {
        rule.beforeVisit(node) { offset, message, fix -> approve(offset, message, fix) }
        node.children.forEach { child -> executeWithApprove(rule, child) }
        rule.afterVisit(node) { offset, message, fix -> approve(offset, message, fix) }
    }
}

